        Kp = (m + r_candidate)//2
        Lp = max(0, Kp - (m - u))
        Up = min(u, Kp)
        if Up - Lp + 1 >= 2 and 0 <= Kp <= m and 0 <= Lp <= Up:
            r = r_candidate
            break
    else:
        return None
    lam = round(rng.uniform(0.25, 0.85), 3)
